      ro: ["Hangare istorice", "Muzeu maritim", "În Tallinn", "Patrimoniu cultural"],
      en: ["Historic hangars", "Maritime museum", "In Tallinn", "Cultural heritage"],
      es: ["Hangares históricos", "Museo marítimo", "En Tallin", "Patrimonio cultural"],
      pt: ["Hangares históricos", "Museu marítimo", "Em Tallinn", "Património cultural"],
      fr: ["Hangars historiques", "Musée maritime", "À Tallinn", "Héritage culturel"],
